edges = set()
for i in range(13):
    for j in [1, 2, 3]:
        u = i
        v = (i + j) % 13
        if u > v:
            u, v = v, u
        edges.add((u, v))

print(f"Number of edges: {len(edges)}")
degrees = {i: 0 for i in range(13)}
for u, v in edges:
    degrees[u] += 1
    degrees[v] += 1

print(f"Degrees: {degrees}")
print(f"Edges: {sorted(list(edges))}")
